#include "ramz.h"\n\n#include <cerrno>\n#include <climits>\n#include <cstdlib>\n#include <cstring>\n#include <fstream>\n#include <iostream>\n#include <string>\n#include <sys/stat.h>\n#include <sys/types.h>\n#include <sys/wait.h>\n#include <unistd.h>\n#include <vector>\n\nnamespace {\nstd::string config_path() {\n  const char *home = std::getenv("HOME");\n  return std::string(home ? home : ".") + "/.config/ramz.conf";\n}\n\nbool parse_size(const std::string &text, size_t *out) {\n  if (!out || text.empty() || text[0] == '-') return false;\n  errno = 0;\n  char *end = nullptr;\n  const unsigned long long value = std::strtoull(text.c_str(), &end, 10);\n  if (errno == ERANGE || end == text.c_str() || *end != '\0' ||\n      value > static_cast<unsigned long long>(SIZE_MAX)) return false;\n  *out = static_cast<size_t>(value);\n  return true;\n}\n\nbool parse_int(const std::string &text, int *out) {\n  if (!out || text.empty()) return false;\n  errno = 0;\n  char *end = nullptr;\n  const long value = std::strtol(text.c_str(), &end, 10);\n  if (errno == ERANGE || end == text.c_str() || *end != '\0' ||\n      value < INT_MIN || value > INT_MAX) return false;\n  *out = static_cast<int>(value);\n  return true;\n}\n\nbool make_parent_directory(const std::string &path) {\n  const size_t slash = path.find_last_of('/');\n  if (slash == std::string::npos || slash == 0) return true;\n  const std::string parent = path.substr(0, slash);\n  std::string current;\n  size_t start = 0;\n  if (parent[0] == '/') { current = "/"; start = 1; }\n  while (start < parent.size()) {\n    const size_t next = parent.find('/', start);\n    const std::string part = parent.substr(start, next == std::string::npos ? std::string::npos : next - start);\n    if (!part.empty()) {\n      if (!current.empty() && current.back() != '/') current += '/';\n      current += part;\n      if (mkdir(current.c_str(), 0700) != 0 && errno != EEXIST) return false;\n    }\n    if (next == std::string::npos) break;\n    start = next + 1;\n  }\n  return true;\n}\n\nvoid defaults(ramz_config &c) { ramz_config_default(&c); }\n\nvoid load(ramz_config &c) {\n  std::ifstream f(config_path());\n  if (!f) return;\n  std::string key, value;\n  while (std::getline(f, key, '=')) {\n    if (!std::getline(f, value)) break;\n    if (key == "algorithm") {\n      if (value == "lz4") c.algorithm = RAMZ_LZ4;\n      else if (value == "zstd") c.algorithm = RAMZ_ZSTD;\n    } else if (key == "block_bytes") {\n      parse_size(value, &c.min_compress_bytes);\n    } else if (key == "min_savings") {\n      parse_size(value, &c.min_savings_bytes);\n    } else if (key == "max_stored_bytes") {\n      parse_size(value, &c.max_stored_bytes);\n    } else if (key == "zstd_level") {\n      parse_int(value, &c.zstd_level);\n    } else if (key == "max_cpu_percent") {\n      parse_int(value, &c.max_cpu_percent);\n    }\n  }\n}\n\nvoid print_config(const ramz_config &c) {\n  std::cout << "algorithm=" << (c.algorithm == RAMZ_ZSTD ? "zstd" : "lz4") << '\n'\n            << "block_bytes=" << c.min_compress_bytes << '\n'\n            << "min_savings=" << c.min_savings_bytes << '\n'\n            << "max_stored_bytes=" << c.max_stored_bytes << '\n'\n            << "zstd_level=" << c.zstd_level << '\n'\n            << "max_cpu_percent=" << c.max_cpu_percent << '\n';\n}\n\nvoid help() {\n  std::cout << "ramz: explicit userspace compressed-block store\n\n"\n            << "Usage:\n  ramz status\n  ramz stats\n  ramz benchmark [--bytes N] [--algorithm lz4|zstd]\n"\n            << "  ramz config [--algorithm lz4|zstd] [--block-bytes N] [--min-savings N]\n"\n            << "              [--max-stored-bytes N] [--zstd-level 1..22] [--max-cpu-percent 1..100]\n\n"\n            << "config writes a local profile used by this CLI. It never changes arbitrary processes.\n"\n            << "RAMZ-aware programs configure their own in-process store through libramz.\n";\n}\n\nbool has_option(int argc, char **argv, const char *option) {\n  for (int i = 2; i < argc; ++i) if (std::strcmp(argv[i], option) == 0) return true;\n  return false;\n}\n}  // namespace\n\nint main(int argc, char **argv) {\n  if (argc < 2) { help(); return 2; }\n  const std::string command = argv[1];\n  ramz_config c;\n  defaults(c);\n  load(c);\n\n  if (command == "status") {\n    std::cout << "ramz mode=explicit-blocks root=not-required transparent-process-compression=disabled\n";\n    print_config(c);\n    return 0;\n  }\n  if (command == "stats") {\n    std::cout << "scope=ramz CLI process only\noriginal_bytes=0\nstored_payload_bytes=0\n"\n              << "metadata_bytes=0\ncompressed_blocks=0\n";\n    return 0;\n  }\n  if (command == "benchmark") {\n    std::vector<char *> args;\n    args.push_back(const_cast<char *>("ramz-benchmark"));\n    for (int i = 2; i < argc; ++i) args.push_back(argv[i]);\n    std::string configured_algorithm;\n    if (!has_option(argc, argv, "--algorithm")) {\n      configured_algorithm = c.algorithm == RAMZ_ZSTD ? "zstd" : "lz4";\n      args.push_back(const_cast<char *>("--algorithm"));\n      args.push_back(configured_algorithm.data());\n    }\n    args.push_back(nullptr);\n    const pid_t child = fork();\n    if (child < 0) { std::cerr << "cannot start benchmark\n"; return 1; }\n    if (child == 0) { execvp(args[0], args.data()); _exit(127); }\n    int status = 0;\n    if (waitpid(child, &status, 0) < 0) { std::cerr << "benchmark wait failed\n"; return 1; }\n    return WIFEXITED(status) ? WEXITSTATUS(status) : 1;\n  }\n  if (command != "config") { help(); return 2; }\n\n  for (int i = 2; i < argc; ++i) {\n    auto require = [&](const char *name) -> const char * {\n      if (i + 1 >= argc) { std::cerr << "missing value for " << name << '\n'; std::exit(2); }\n      return argv[++i];\n    };\n    const std::string arg = argv[i];\n    if (arg == "--algorithm") {\n      const std::string v = require("--algorithm");\n      if (v == "lz4") c.algorithm = RAMZ_LZ4;\n      else if (v == "zstd") c.algorithm = RAMZ_ZSTD;\n      else { std::cerr << "algorithm must be lz4 or zstd\n"; return 2; }\n    } else if (arg == "--block-bytes") {\n      if (!parse_size(require("--block-bytes"), &c.min_compress_bytes)) { std::cerr << "invalid block size\n"; return 2; }\n    } else if (arg == "--min-savings") {\n      if (!parse_size(require("--min-savings"), &c.min_savings_bytes)) { std::cerr << "invalid savings\n"; return 2; }\n    } else if (arg == "--max-stored-bytes") {\n      if (!parse_size(require("--max-stored-bytes"), &c.max_stored_bytes)) { std::cerr << "invalid storage limit\n"; return 2; }\n    } else if (arg == "--zstd-level") {\n      if (!parse_int(require("--zstd-level"), &c.zstd_level)) { std::cerr << "invalid zstd level\n"; return 2; }\n    } else if (arg == "--max-cpu-percent") {\n      if (!parse_int(require("--max-cpu-percent"), &c.max_cpu_percent)) { std::cerr << "invalid CPU limit\n"; return 2; }\n    } else { std::cerr << "unknown option: " << arg << '\n'; return 2; }\n  }\n\n  if ((c.algorithm != RAMZ_LZ4 && c.algorithm != RAMZ_ZSTD) || c.min_compress_bytes == 0 ||\n      c.zstd_level < 1 || c.zstd_level > 22 || c.max_cpu_percent < 1 || c.max_cpu_percent > 100) {\n    std::cerr << "invalid configuration\n";\n    return 2;\n  }\n  const std::string p = config_path();\n  if (!make_parent_directory(p)) { std::cerr << "cannot create configuration directory\n"; return 1; }\n  std::ofstream f(p, std::ios::trunc);\n  if (!f) { std::cerr << "cannot write configuration\n"; return 1; }\n  f << "algorithm=" << (c.algorithm == RAMZ_ZSTD ? "zstd" : "lz4") << '\n'\n    << "block_bytes=" << c.min_compress_bytes << '\n'\n    << "min_savings=" << c.min_savings_bytes << '\n'\n    << "max_stored_bytes=" << c.max_stored_bytes << '\n'\n    << "zstd_level=" << c.zstd_level << '\n'\n    << "max_cpu_percent=" << c.max_cpu_percent << '\n';\n  if (!f) { std::cerr << "cannot write configuration\n"; return 1; }\n  print_config(c);\n  return 0;\n}\n